        $paperDimensions = [$paperDimensions[1], $paperDimensions[0]];
    }
    $public = \Illuminate\Support\Facades\Storage::disk('public');
    $img = static function ($path) use ($public): ?string { if (is_array($path)) $path = array_values($path)[0] ?? null; if (!$path || str_contains($path, '/')) { $full = $path; } else { $full = null; } if (!$full || !$public->exists($full)) return null; $mime = mime_content_type($public->path($full)) ?: 'image/png'; return 'data:'.$mime.';base64,'.base64_encode($public->get($full)); };
    $logo = $h['logo_path'] ?? null; if ($logo && !str_contains((string)$logo, '/')) $logo = 'foundation-sk/logos/'.$logo;
    $stamp = $b['signature']['stamp_path'] ?? null; if ($stamp && !str_contains((string)$stamp, '/')) $stamp = 'foundation-sk/signature-stamps/'.$stamp;
    $logoUrl = $img($logo); $stampUrl = $img($stamp);
    $parts = static fn ($key) => array_values(array_filter(array_map('trim', preg_split('/;[\r\n]*/', (string)($s[$key] ?? '')))));
    $clean = static fn ($text) => preg_replace('/^(Pertama|Kedua|Ketiga)\s*:\s*/i', '', trim((string)$text));
